122		Object loadServiceCapabilities(String serviceUrl) throws IOException {
123			HttpGet request = new HttpGet(serviceUrl);
124			request.setHeader(new BasicHeader(HttpHeaders.ACCEPT, ACCEPT_SERVICE_CAPABILITIES));
125			ClassicHttpResponse httpResponse = execute(request, URI.create(serviceUrl), "retrieve help");
126			validateResponse(httpResponse, serviceUrl);
127			HttpEntity httpEntity = httpResponse.getEntity();
128			ContentType contentType = ContentType.create(httpEntity.getContentType());
129			if (contentType.getMimeType().equals("text/plain")) {
130				return getContent(httpEntity);
131			}
132			return parseJsonMetadata(httpEntity);
133		}
