144		private void validateResponse(ClassicHttpResponse httpResponse, String serviceUrl) {
145			if (httpResponse.getEntity() == null) {
146				throw new ReportableException("No content received from server '" + serviceUrl + "'");
147			}
148			if (httpResponse.getCode() != 200) {
149				throw createException(serviceUrl, httpResponse);
150			}
