156					ContentType.create(httpEntity.getContentType()));
157			response.setContent(FileCopyUtils.copyToByteArray(httpEntity.getContent()));
158			String fileName = extractFileName(httpResponse.getFirstHeader("Content-Disposition"));
159			if (fileName != null) {
160				response.setFileName(fileName);
161			}
162			return response;
163		}
