197		private ReportableException createException(String url, ClassicHttpResponse httpResponse) {
198			StatusLine statusLine = new StatusLine(httpResponse);
199			String message = "Initializr service call failed using '" + url + "' - service returned "
200					+ statusLine.getReasonPhrase();
201			String error = extractMessage(httpResponse.getEntity());
202			if (StringUtils.hasText(error)) {
203				message += ": '" + error + "'";
204			}
205			else {
206				int statusCode = statusLine.getStatusCode();
207				message += " (unexpected " + statusCode + " error)";
208			}
209			return new ReportableException(message);
210		}
